using System.Text.Json;
using System.Text.Json.Serialization;

namespace MyAnimelist.NET
{
    // Hooks into the generated clients (see AutoGeneratedClient.cs).
    // MAL returns some numbers as strings, although the spec declares them as integers (e.g. statistics.status.watching on anime details).
    internal static class MyAnimelistJsonSerializerSettings
    {
        public static void Update(JsonSerializerOptions settings)
        {
            settings.NumberHandling |= JsonNumberHandling.AllowReadingFromString;
        }
    }

    public partial class Client
    {
        static partial void UpdateJsonSerializerSettings(JsonSerializerOptions settings) => MyAnimelistJsonSerializerSettings.Update(settings);
    }

    public partial class AnimeClient
    {
        static partial void UpdateJsonSerializerSettings(JsonSerializerOptions settings) => MyAnimelistJsonSerializerSettings.Update(settings);
    }

    public partial class ForumClient
    {
        static partial void UpdateJsonSerializerSettings(JsonSerializerOptions settings) => MyAnimelistJsonSerializerSettings.Update(settings);
    }

    public partial class MangaClient
    {
        static partial void UpdateJsonSerializerSettings(JsonSerializerOptions settings) => MyAnimelistJsonSerializerSettings.Update(settings);
    }

    public partial class UsersClient
    {
        static partial void UpdateJsonSerializerSettings(JsonSerializerOptions settings) => MyAnimelistJsonSerializerSettings.Update(settings);
    }
}
